#include <WiFi.h>
#include <ArduinoOTA.h>

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  ArduinoOTA.setHostname("{{hostname}}");
  ArduinoOTA.begin();
  Serial.println(WiFi.localIP());
}

void loop() { ArduinoOTA.handle(); }
